after.content:
:root {
    color-scheme: light;
    --ink: #1c2638;
    --muted: #78859a;
    --line: #e8ecf2;
    --green: #23896c;
    --green-dark: #1c755c;
    --page: #f5f7fb;
    --card: #fff;
    font-family: "DM Sans", sans-serif;
    font-synthesis: none;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

* {
    box-sizing: border-box;
}

body {
    min-width: 320px;
    margin: 0;
    background:
        radial-gradient(ellipse at 50% 0, rgba(220, 237, 232, .52), transparent 34rem),
        var(--page);
    color: var(--ink);
}

button,
input,
textarea {
    font: inherit;
}

button {
    cursor: pointer;
}

.page-shell {
    width: min(100% - 48px, 920px);
    margin: 0 auto;
}

.topbar {
    height: 82px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid rgba(219, 225, 233, .8);
}

.brand {
    display: inline-flex;
    align-items: center;
    gap: 11px;
    color: inherit;
    text-decoration: none;
}

.brand-mark {
    width: 38px;
    height: 38px;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: #e4f2ed;
    color: var(--green);
}

.brand-mark svg {
    width: 21px;
    height: 21px;
}

.brand-name {
    font-family: Manrope, sans-serif;
    font-size: 15px;
    font-weight: 800;
    letter-spacing: -.5px;
}

.brand-name span {
    color: var(--green);
}

.topbar-caption {
    color: #8994a5;
    font-size: 12px;
}

main {
    max-width: 720px;
    margin: 0 auto;
}

.intro {
    padding: 66px 0 33px;
    text-align: center;
}

.eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: var(--green);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.3px;
}

.eyebrow-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: #43b18c;
    box-shadow: 0 0 0 4px #e3f2ed;
