h1,
h2,
h3,
p {
    margin: 0;
}

h1 {
    margin-top: 15px;
    font-family: Manrope, sans-serif;
    font-size: clamp(32px, 5vw, 46px);
    font-weight: 800;
    letter-spacing: -2.3px;
    line-height: 1.15;
}

h1 span {
    color: var(--green);
}

.mobile-break {
    display: none;
}

.intro-copy {
    margin-top: 14px;
    color: var(--muted);
    font-size: 15px;
}

.search-card,
.empty-card,
.data-card,
.document-card {
    border: 1px solid var(--line);
    border-radius: 16px;
    background: var(--card);
    box-shadow: 0 8px 26px rgba(30, 48, 73, .035);
