.search-card {
    padding: 25px 27px 19px;
}

.search-card-heading,
.section-heading {
    display: flex;
    align-items: flex-start;
    gap: 13px;
}

.step-number {
    width: 30px;
    height: 30px;
    flex: 0 0 30px;
    display: grid;
    place-items: center;
    border: 1px solid #dfece7;
    border-radius: 9px;
    background: #f0f7f4;
    color: var(--green);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: .3px;
