.section-heading p {
    margin-top: 4px;
    color: var(--muted);
    font-size: 12px;
}

.search-row {
    display: flex;
    gap: 10px;
    margin-top: 22px;
}

.input-wrap {
    position: relative;
    flex: 1;
}

