:root {
    color-scheme: light;
    --ink: #1c2638;
    --muted: #78859a;
    --line: #e8ecf2;
    --green: #23896c;
    --green-dark: #1c755c;
    --page: #f5f7fb;
    --card: #fff;
    font-family: "DM Sans", sans-serif;
    font-synthesis: none;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

* {
    box-sizing: border-box;
}

body {
    min-width: 320px;
    margin: 0;
    background:
        radial-gradient(ellipse at 50% 0, rgba(220, 237, 232, .52), transparent 34rem),
        var(--page);
    color: var(--ink);
}

button,
input,
textarea {
    font: inherit;
}

button {
    cursor: pointer;
}

