    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid rgba(219, 225, 233, .8);
}

.brand {
    display: inline-flex;
    align-items: center;
    gap: 11px;
    color: inherit;
    text-decoration: none;
}

