result.content:
const API_ENDPOINT = "https://api.checko.ru/v2/company";
const REQUEST_TIMEOUT_MS = 20000;

const innInput = document.querySelector("#inn-input");
const apiKeyInput = document.querySelector("#api-key");
const searchButton = document.querySelector("#search-button");
const searchButtonLabel = searchButton.querySelector("span");
const searchMessage = document.querySelector("#search-message");
const emptyState = document.querySelector("#results-empty");
const companyCard = document.querySelector("#company-data");
const companyName = document.querySelector("#company-name");
const dataRows = document.querySelector("#company-data-rows");

const fieldTitles = {
    "ДатаОГРН": "Дата присвоения ОГРН",
    "ДатаРег": "Дата регистрации",
    DataReg: "Дата регистрации",
    DataOgrn: "Дата присвоения ОГРН",
    "ИНН": "ИНН",
    Inn: "ИНН",
    "КПП": "КПП",
    Kpp: "КПП",
    "НаимАнгл": "Наименование на английском",
    NaimAngl: "Наименование на английском",
    "НаимПолн": "Полное наименование",
    NaimPoln: "Полное наименование",
    "НаимСокр": "Сокращенное наименование",
    NaimSokr: "Сокращенное наименование",
    "ОГРН": "ОГРН",
    Ogrn: "ОГРН",
    "ОКПО": "ОКПО",
    Okpo: "ОКПО"
};

function isRecord(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

function displayFieldName(key) {
    return fieldTitles[key] || key;
}

function formatValue(value) {
    if (value === null || value === undefined || value === "") {
        return "—";
    }

    if (typeof value === "boolean") {
        return value ? "Да" : "Нет";
    }

    return String(value);
}

function flattenData(value, prefix, rows) {
    if (Array.isArray(value)) {
        if (value.length === 0) {
            rows.push([prefix, "—"]);
            return;
        }

        if (value.every((item) => !isRecord(item) && !Array.isArray(item))) {
            rows.push([prefix, value.map(formatValue).join(", ")]);
            return;
        }

        value.forEach((item, index) => {
            flattenData(item, `${prefix} · ${index + 1}`, rows);
        });
        return;
    }

    if (isRecord(value)) {
        const entries = Object.entries(value);
        if (entries.length === 0) {
            rows.push([prefix, "—"]);
            return;
        }

        entries.forEach(([key, nestedValue]) => {
            const label = displayFieldName(key);
            flattenData(nestedValue, prefix ? `${prefix} → ${label}` : label, rows);
        });
        return;
    }

    rows.push([prefix || "Данные", formatValue(value)]);
}

function findCompanyName(value) {
    if (!isRecord(value)) {
        return "";
    }

    const preferredKeys = ["НаимПолн", "НаимСокр", "Наименование", "name"];
    for (const key of preferredKeys) {
        if (typeof value[key] === "string" && value[key].trim()) {
            return value[key].trim();
        }
    }

    for (const nestedValue of Object.values(value)) {
        if (isRecord(nestedValue)) {
            const name = findCompanyName(nestedValue);
            if (name) {
                return name;
            }
        }
    }

    return "";
}

function renderCompanyData(payload) {
    if (!isRecord(payload)) {
        throw new Error("Сервис вернул данные в неожиданном формате.");
    }

    const company = isRecord(payload.data) ? payload.data : payload;
    const rows = [];
    flattenData(company, "", rows);

    if (rows.length === 0) {
        throw new Error("Сервис не вернул данные организации.");
    }

    const fragment = document.createDocumentFragment();
    rows.forEach(([label, value]) => {
        const row = document.createElement("tr");
        const heading = document.createElement("th");
        const cell = document.createElement("td");

        heading.scope = "row";
        heading.textContent = label;
        cell.textContent = value;
        row.append(heading, cell);
        fragment.append(row);
    });

    dataRows.replaceChildren(fragment);
    companyName.textContent = findCompanyName(company) || "Данные организации";
    emptyState.hidden = true;
    companyCard.hidden = false;
}

function showMessage(message, isError) {
    searchMessage.textContent = message;
    searchMessage.classList.toggle("is-error", isError);
    searchMessage.hidden = !message;
}

function getServiceError(payload) {
    if (!isRecord(payload)) {
        return "";
    }

    const error = payload.error || payload.Error || payload.message;
    return typeof error === "string" ? error : "";
}

async function searchCompany() {
    const inn = innInput.value.trim();
    const apiKey = apiKeyInput.value.trim();

    if (!/^\d{10}(?:\d{2})?$/.test(inn)) {
        showMessage("Введите ИНН из 10 цифр для организации или 12 цифр для ИП.", true);
        innInput.focus();
        return;
    }

    if (!apiKey) {
        showMessage("Введите ключ API для поиска.", true);
        apiKeyInput.focus();
        return;
    }

    apiKeyInput.value = "";
    showMessage("Выполняется поиск…", false);
    searchButton.disabled = true;
    searchButtonLabel.textContent = "Ищем…";
    companyCard.hidden = true;
    emptyState.hidden = false;

    const controller = new AbortController();
    const timeoutId = window.setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    const url = new URL(API_ENDPOINT);
    url.searchParams.set("key", apiKey);
    url.searchParams.set("inn", inn);

    try {
        const response = await fetch(url, { signal: controller.signal });
        let payload;

        try {
            payload = await response.json();
        } catch {
            throw new Error("Сервис вернул ответ, который не удалось прочитать.");
        }

        if (!response.ok) {
            throw new Error(getServiceError(payload) || `Ошибка сервиса (${response.status}).`);
        }

        const serviceError = getServiceError(payload);
        if (serviceError || (isRecord(payload) && payload.success === false)) {
            throw new Error(serviceError || "Сервис не смог найти организацию.");
        }

        renderCompanyData(payload);
        showMessage("", false);
    } catch (error) {
        if (error.name === "AbortError") {
            showMessage("Превышено время ожидания ответа. Попробуйте ещё раз.", true);
        } else if (error instanceof TypeError) {
            showMessage("Не удалось подключиться к API. Проверьте соединение и настройки CORS сервиса.", true);
        } else {
            showMessage(error.message || "Не удалось получить данные организации.", true);
        }
    } finally {
        window.clearTimeout(timeoutId);
        searchButton.disabled = false;
        searchButtonLabel.textContent = "Найти компанию";
    }
}

searchButton.addEventListener("click", searchCompany);
innInput.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
        searchCompany();
    }
});
apiKeyInput.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
        searchCompany();
