.card-overline {
    color: #929eaf;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1px;
}

.data-card-title h3 {
    margin-top: 6px;
    font-family: Manrope, sans-serif;
    font-size: 16px;
    font-weight: 700;
}

.status-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 10px;
    border-radius: 20px;
    background: #edf7f2;
    color: #298361;
    font-size: 10px;
    white-space: nowrap;
}

