.ready-indicator > span:first-child {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #45ac80;
}

.table-scroll {
    overflow-x: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
    text-align: left;
}

tbody tr {
    border-top: 1px solid #edf0f4;
}

th,
td {
    padding: 13px 24px;
    font-size: 12px;
}

th {
    width: 34%;
    color: #8995a7;
    font-weight: 500;
}

td {
    color: var(--ink);
    font-weight: 500;
}

.document-card {
    overflow: hidden;
}

.document-toolbar {
    min-height: 56px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 0 18px;
    border-bottom: 1px solid #edf0f4;
}

.document-label {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    color: #445166;
    font-size: 11px;
    font-weight: 600;
}

.document-icon {
    width: 27px;
    height: 27px;
    display: grid;
    place-items: center;
    border-radius: 7px;
    background: #f0f3f8;
    color: #75839a;
}

.document-icon svg {
    width: 17px;
    height: 17px;
}

.copy-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 7px 10px;
    border: 1px solid #e5e9ef;
    border-radius: 7px;
    background: #fff;
    color: #566378;
    font-size: 10px;
    font-weight: 600;
    transition: background .2s, color .2s, border-color .2s;
}

.copy-button:not(:disabled):hover {
    border-color: #c8e3d8;
    background: #f2f8f5;
    color: var(--green-dark);
}

.copy-button:disabled {
    cursor: not-allowed;
    opacity: .48;
}

.copy-button svg {
    width: 16px;

