permissionRequest.newFileContents:
:root {
    color-scheme: light;
    --ink: #1c2638;
    --muted: #78859a;
    --line: #e8ecf2;
    --green: #23896c;
    --green-dark: #1c755c;
    --page: #f5f7fb;
    --card: #fff;
    font-family: "DM Sans", sans-serif;
    font-synthesis: none;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

* {
    box-sizing: border-box;
}

body {
    min-width: 320px;
    margin: 0;
    background:
        radial-gradient(ellipse at 50% 0, rgba(220, 237, 232, .52), transparent 34rem),
        var(--page);
    color: var(--ink);
}

button,
input,
textarea {
    font: inherit;
}

button {
    cursor: pointer;
}

.page-shell {
    width: min(100% - 48px, 920px);
    margin: 0 auto;
}

.topbar {
    height: 82px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid rgba(219, 225, 233, .8);
}

.brand {
    display: inline-flex;
    align-items: center;
    gap: 11px;
    color: inherit;
    text-decoration: none;
}

.brand-mark {
    width: 38px;
    height: 38px;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: #e4f2ed;
    color: var(--green);
}

.brand-mark svg {
    width: 21px;
    height: 21px;
}

.brand-name {
    font-family: Manrope, sans-serif;
    font-size: 15px;
    font-weight: 800;
    letter-spacing: -.5px;
}

.brand-name span {
    color: var(--green);
}

.topbar-caption {
    color: #8994a5;
    font-size: 12px;
}

main {
    max-width: 720px;
    margin: 0 auto;
}

.intro {
    padding: 66px 0 33px;
    text-align: center;
}

.eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: var(--green);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.3px;
}

.eyebrow-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: #43b18c;
    box-shadow: 0 0 0 4px #e3f2ed;
}

h1,
h2,
h3,
p {
    margin: 0;
}

h1 {
    margin-top: 15px;
    font-family: Manrope, sans-serif;
    font-size: clamp(32px, 5vw, 46px);
    font-weight: 800;
    letter-spacing: -2.3px;
    line-height: 1.15;
}

h1 span {
    color: var(--green);
}

.mobile-break {
    display: none;
}

.intro-copy {
    margin-top: 14px;
    color: var(--muted);
    font-size: 15px;
}

.search-card,
.empty-card,
.data-card {
    border: 1px solid var(--line);
    border-radius: 16px;
    background: var(--card);
    box-shadow: 0 8px 26px rgba(30, 48, 73, .035);
}

.search-card {
    padding: 25px 27px 19px;
}

.search-card-heading,
.section-heading {
    display: flex;
    align-items: flex-start;
    gap: 13px;
}

.step-number {
    width: 30px;
    height: 30px;
    flex: 0 0 30px;
    display: grid;
    place-items: center;
    border: 1px solid #dfece7;
    border-radius: 9px;
    background: #f0f7f4;
    color: var(--green);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: .3px;
}

.search-card-heading h2,
.section-heading h2 {
    padding-top: 1px;
    font-family: Manrope, sans-serif;
    font-size: 16px;
    font-weight: 700;
    letter-spacing: -.35px;
}

.search-card-heading p,
.section-heading p {
    margin-top: 4px;
    color: var(--muted);
    font-size: 12px;
}

.search-row {
    display: flex;
    gap: 10px;
    margin-top: 22px;
}

.input-wrap {
    position: relative;
    flex: 1;
}

.input-icon {
    position: absolute;
    top: 50%;
    left: 15px;
    width: 20px;
    height: 20px;
    transform: translateY(-50%);
    color: #9aa5b5;
    pointer-events: none;
}

.input-wrap input {
    width: 100%;
    height: 48px;
    padding: 0 14px 0 44px;
    border: 1px solid #e3e8ef;
    border-radius: 9px;
    outline: none;
    background: #fbfcfe;
    color: var(--ink);
    font-size: 13px;
    transition: border-color .2s, box-shadow .2s, background .2s;
}

.input-wrap input::placeholder {
    color: #a4adba;
}

.input-wrap input:focus {
    border-color: #69b49a;
    background: #fff;
    box-shadow: 0 0 0 3px rgba(35, 137, 108, .1);
}

.api-key-input {
    width: 170px;
    height: 48px;
    padding: 0 12px;
    border: 1px solid #e3e8ef;
    border-radius: 9px;
    outline: none;
    background: #fbfcfe;
    color: var(--ink);
    font-size: 12px;
    transition: border-color .2s, box-shadow .2s, background .2s;
}

.api-key-input::placeholder {
    color: #a4adba;
}

.api-key-input:focus {
    border-color: #69b49a;
    background: #fff;
    box-shadow: 0 0 0 3px rgba(35, 137, 108, .1);
}

.primary-button {
    min-width: 160px;
    height: 48px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    padding: 0 16px;
    border: 0;
    border-radius: 9px;
    background: var(--green);
    color: white;
    font-size: 12px;
    font-weight: 600;
    transition: background .2s, transform .2s, box-shadow .2s;
}

.primary-button:hover {
    transform: translateY(-1px);
    background: var(--green-dark);
    box-shadow: 0 5px 12px rgba(35, 137, 108, .2);
}

.primary-button:focus-visible {
    outline: 3px solid rgba(35, 137, 108, .22);
    outline-offset: 2px;
}

.primary-button svg {
    width: 17px;
    height: 17px;
}

.search-footnote {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 12px;
    color: #97a1b0;
    font-size: 10px;
}

.search-footnote svg {
    width: 14px;
    height: 14px;
    flex: 0 0 14px;
}

.search-message {
    margin-top: 12px;
    color: #b54747;
    font-size: 12px;
    line-height: 1.5;
}

.results-section {
    margin-top: 39px;
}

.section-heading {
    margin-bottom: 15px;
}

.empty-card {
    min-height: 207px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 24px;
    text-align: center;
}

.empty-illustration {
    width: 64px;
    height: 64px;
    margin-bottom: 12px;
}

.empty-illustration svg {
    width: 100%;
    height: 100%;
}

.empty-card h3 {
    font-family: Manrope, sans-serif;
    font-size: 13px;
    font-weight: 700;
}

.empty-card p {
    margin-top: 6px;
    color: #929eaf;
    font-size: 11px;
}

.data-card {
    overflow: hidden;
}

.data-card-title {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 22px 24px;
}

.card-overline {
    color: #929eaf;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1px;
}

.data-card-title h3 {
    margin-top: 6px;
    font-family: Manrope, sans-serif;
    font-size: 16px;
    font-weight: 700;
}

.table-scroll {
    overflow-x: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
    text-align: left;
}

tbody tr {
    border-top: 1px solid #edf0f4;
}

th,
td {
    padding: 13px 24px;
    font-size: 12px;
}

th {
    width: 34%;
    color: #8995a7;
    font-weight: 500;
}

td {
    color: var(--ink);
    font-weight: 500;
}

.footer {
    min-height: 63px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    border-top: 1px solid rgba(219, 225, 233, .8);
    color: #9aa4b2;
    font-size: 10px;
}

.footer span:first-child {
    color: #758196;
    font-weight: 700;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    clip-path: inset(50%);
}

[hidden] {
    display: none !important;
}

@media (max-width: 600px) {
    .page-shell {
        width: min(100% - 32px, 480px);
    }

    .topbar {
        height: 68px;
    }

    .topbar-caption {
        max-width: 110px;
        text-align: right;
        font-size: 10px;
    }

    .intro {
        padding: 51px 0 27px;
    }

    h1 {
        font-size: 35px;
        letter-spacing: -1.7px;
    }

    .mobile-break {
        display: initial;
    }

    .intro-copy {
        max-width: 290px;
        margin: 12px auto 0;
        font-size: 13px;
        line-height: 1.6;
    }

    .search-card {
        padding: 20px 17px 17px;
    }

    .search-row {
        flex-direction: column;
        gap: 9px;
        margin-top: 18px;
    }

    .api-key-input {
        width: 100%;
    }

    .primary-button {
        width: 100%;
    }

    .search-footnote {
        align-items: flex-start;
        line-height: 1.5;
    }

    .results-section {
        margin-top: 32px;
    }

    .empty-card {
        min-height: 190px;
    }

    .data-card-title {
        align-items: flex-start;
        padding: 18px 16px;
    }

    .data-card-title h3 {
        font-size: 14px;
    }

    th,
    td {
        padding: 12px 16px;
        font-size: 11px;
    }

    th {
        width: 42%;
    }

    .footer {
        align-items: flex-start;
        flex-direction: column;
        justify-content: center;
        gap: 5px;
        padding: 12px 0;
    }
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        scroll-behavior: auto !important;
        transition-duration: .01ms !important;
    }
}

