        padding: 18px 16px;
    }

    .data-card-title h3 {
        font-size: 14px;
    }

    th,
    td {
        padding: 12px 16px;
        font-size: 11px;
    }

    th {
        width: 42%;
    }

    .footer {
        align-items: flex-start;
