    height: 17px;
}

.search-footnote {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 12px;
    color: #97a1b0;
    font-size: 10px;
}

.search-footnote svg {
    width: 14px;
    height: 14px;
    flex: 0 0 14px;
}

.search-message {
    margin-top: 12px;
    color: #b54747;
    font-size: 12px;
    line-height: 1.5;
}

.results-section,
.document-section {
    margin-top: 39px;
}

.section-heading {
    margin-bottom: 15px;
}

.empty-card {
