}

.empty-illustration {
    width: 64px;
    height: 64px;
    margin-bottom: 12px;
}

.empty-illustration svg {
    width: 100%;
    height: 100%;
}

.empty-card h3 {
    font-family: Manrope, sans-serif;
    font-size: 13px;
    font-weight: 700;
}

.empty-card p {
    margin-top: 6px;
    color: #929eaf;
    font-size: 11px;
}

.data-card {
    overflow: hidden;
}

.data-card-title {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 22px 24px;
}

.card-overline {
    color: #929eaf;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1px;
}

.data-card-title h3 {
    margin-top: 6px;
    font-family: Manrope, sans-serif;
    font-size: 16px;
    font-weight: 700;
}

.status-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 10px;
    border-radius: 20px;
    background: #edf7f2;
    color: #298361;
    font-size: 10px;
    white-space: nowrap;
}

.status-badge span,
.ready-indicator > span:first-child {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #45ac80;
}

.table-scroll {
    overflow-x: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
    text-align: left;
}

tbody tr {
    border-top: 1px solid #edf0f4;
}

th,
td {
    padding: 13px 24px;
    font-size: 12px;
}

th {
    width: 34%;
    color: #8995a7;
    font-weight: 500;
}

td {
    color: var(--ink);
    font-weight: 500;
}

.document-card {
    overflow: hidden;
}

.document-toolbar {
    min-height: 56px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 0 18px;
    border-bottom: 1px solid #edf0f4;
}

.document-label {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    color: #445166;
    font-size: 11px;
    font-weight: 600;
}

.document-icon {
    width: 27px;
    height: 27px;
    display: grid;
    place-items: center;
    border-radius: 7px;
    background: #f0f3f8;
    color: #75839a;
}

.document-icon svg {
    width: 17px;
    height: 17px;
}

.copy-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 7px 10px;
    border: 1px solid #e5e9ef;
    border-radius: 7px;
    background: #fff;
    color: #566378;
    font-size: 10px;
    font-weight: 600;
    transition: background .2s, color .2s, border-color .2s;
}

.copy-button:not(:disabled):hover {
    border-color: #c8e3d8;
    background: #f2f8f5;
    color: var(--green-dark);
}

.copy-button:disabled {
    cursor: not-allowed;
    opacity: .48;
}

.copy-button svg {
    width: 16px;
    height: 16px;
}

#generated-text {
    width: 100%;
    min-height: 166px;
    display: block;
    resize: vertical;
    padding: 18px 20px;
    border: 0;
    outline: none;
    background: #fff;
    color: #445166;
    font-family: "DM Sans", sans-serif;
    font-size: 12px;
    line-height: 1.8;
}

#generated-text::placeholder {
    color: #a2acba;
}

.document-footer {
    min-height: 39px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 18px;
    border-top: 1px solid #edf0f4;
    background: #fcfdfe;
}

.ready-indicator {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: #8d99a9;
    font-size: 10px;
}

.ready-indicator > span:first-child {
    background: #c3cbd6;
}

.document-format {
    color: #a0a9b6;
    font-size: 10px;
}

.footer {
    min-height: 63px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    border-top: 1px solid rgba(219, 225, 233, .8);
    color: #9aa4b2;
    font-size: 10px;
}

.footer span:first-child {
    color: #758196;
    font-weight: 700;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    clip-path: inset(50%);
}

[hidden] {
    display: none !important;
}

@media (max-width: 600px) {
    .page-shell {
        width: min(100% - 32px, 480px);
    }

    .topbar {
        height: 68px;
    }

    .topbar-caption {
        max-width: 110px;
        text-align: right;
        font-size: 10px;
    }

    .intro {
        padding: 51px 0 27px;
    }

    h1 {
        font-size: 35px;
        letter-spacing: -1.7px;
    }

    .mobile-break {
        display: initial;
    }

    .intro-copy {
        max-width: 290px;
        margin: 12px auto 0;
        font-size: 13px;
        line-height: 1.6;
    }

    .search-card {
        padding: 20px 17px 17px;
    }

    .search-row {
        flex-direction: column;
        gap: 9px;
        margin-top: 18px;
    }

    .api-key-input {
        width: 100%;
    }

    .primary-button {
        width: 100%;
    }

    .search-footnote {
        align-items: flex-start;
        line-height: 1.5;
    }

    .results-section,
    .document-section {
        margin-top: 32px;
    }

    .empty-card {
        min-height: 190px;
    }

    .data-card-title {
        align-items: flex-start;
        padding: 18px 16px;
    }

    .data-card-title h3 {
        font-size: 14px;
    }

    th,
    td {
        padding: 12px 16px;
        font-size: 11px;
    }

    th {
        width: 42%;
    }

    .document-toolbar {
        padding: 0 12px;
    }

    #generated-text {
        min-height: 150px;
        padding: 15px;
    }

    .footer {
        align-items: flex-start;
        flex-direction: column;
        justify-content: center;
        gap: 5px;
        padding: 12px 0;
    }
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        scroll-behavior: auto !important;
        transition-duration: .01ms !important;
    }
}

